function logical(syntax){let cells=0,tokenBytes=0,depth=0;const walk=(nodes,level=0)=>{depth=Math.max(depth,level);for(const node of nodes){cells++;tokenBytes+=node.tag==='token'?Buffer.byteLength(node.text):node.tag==='group'?2:0;if(node.nodes)walk(node.nodes,level+1);}};walk(syntax);return {cells,tokenBytes,depth};}

