function jsonObserved(run,mode){
 const stringify=Object.getOwnPropertyDescriptor(JSON,'stringify'),parse=Object.getOwnPropertyDescriptor(JSON,'parse'),number=Object.getOwnPropertyDescriptor(Number,'isInteger'),toJSON=Object.getOwnPropertyDescriptor(Object.prototype,'toJSON'),buffer=Object.getOwnPropertyDescriptor(globalThis,'Buffer'),owner=Buffer,byteLength=Object.getOwnPropertyDescriptor(Buffer,'byteLength'),tape=[];let value,error;
 try{
  if(mode==='stringify')Object.defineProperty(JSON,'stringify',{...stringify,value:function(...args){tape.push({op:'stringify',args});return Reflect.apply(stringify.value,this,args);}});
  if(mode==='parse')Object.defineProperty(JSON,'parse',{...parse,value:function(...args){tape.push({op:'parse',args});return Reflect.apply(parse.value,this,args);}});
  if(mode==='number')Object.defineProperty(Number,'isInteger',{...number,value:function(...args){tape.push({op:'isInteger',args});return Reflect.apply(number.value,this,args);}});
  if(mode==='byteLength')Object.defineProperty(owner,'byteLength',{...byteLength,value:function(...args){tape.push({op:'byteLength',args});return Reflect.apply(byteLength.value,this,args);}});
  if(mode==='bufferOwner'){const replacement={byteLength:function(...args){tape.push({op:'changed-buffer-byteLength',args});return Reflect.apply(byteLength.value,owner,args);}};if(Object.hasOwn(buffer,'value'))Object.defineProperty(globalThis,'Buffer',{...buffer,value:replacement});else Reflect.apply(buffer.set,globalThis,[replacement]);}
  if(mode==='toJSON')Object.defineProperty(Object.prototype,'toJSON',{configurable:true,value:function(key){tape.push({op:'toJSON',key,value:this});return this;}});
  try{value=run();}catch(caught){error={name:caught.name,message:caught.message};}
 }finally{if(!Object.hasOwn(buffer,'value'))Reflect.apply(buffer.set,globalThis,[owner]);Object.defineProperty(globalThis,'Buffer',buffer);Object.defineProperty(owner,'byteLength',byteLength);Object.defineProperty(JSON,'stringify',stringify);Object.defineProperty(JSON,'parse',parse);Object.defineProperty(Number,'isInteger',number);if(toJSON)Object.defineProperty(Object.prototype,'toJSON',toJSON);else delete Object.prototype.toJSON;}
 return {value,error,tape};
}
